  const string Output="docs/ProductionReports/Part12C/";public bool preview,reload;static Part12CProbe active;string key;readonly List<string> checks=new List<string>(),errors=new List<string>(),warnings=new List<string>();readonly Dictionary<string,string> player=new Dictionary<string,string>();
  void Awake(){if(active!=null){Destroy(gameObject);return;}active=this;DontDestroyOnLoad(gameObject);Directory.CreateDirectory(Output);foreach(var suffix in new[]{"",".backup",".corrupt"}){var k=GameplayProgress.StorageKey+suffix;player[k]=PlayerPrefs.HasKey(k)?PlayerPrefs.GetString(k):null;}key=SessionState.GetString("Part12C.Key","");GameplayProgress.UseTestProfile();if(!reload){var d=new ProgressData{completedTutorials=new List<string>{PawGuide.BasicId}};d.presentation.manualLocale=preview?"tr":null;d.presentation.coins=1234567;d.presentation.gems=17;d.levels.Add(new LevelRecord{level=1,bestStars=3,rewardClaimed=true});PlayerPrefs.SetString(key,JsonUtility.ToJson(d));PlayerPrefs.Save();}Bind();GameplayLevelCatalog.ResetSelection();Application.logMessageReceived+=Log;}
