  IEnumerator Start(){if(preview)yield break;var stack=new Stack<IEnumerator>();stack.Push(reload?Reload():Run());string failure=null;while(stack.Count>0){object next=null;bool more=false;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception e){failure=e.ToString();break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested&&!(next is CustomYieldInstruction)){stack.Push(nested);continue;}yield return next;}bool intact=player.All(p=>p.Value==null?!PlayerPrefs.HasKey(p.Key):PlayerPrefs.GetString(p.Key)==p.Value);File.WriteAllText(Output+(reload?"RELOAD_TESTS.json":"UNITY_TESTS.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{success=failure==null&&errors.Count==0&&warnings.Count==0&&intact,failure,count=checks.Count,checks,errors,warnings,missingKeys=L.Missing.ToArray(),playerSaveAndBackupIntact=intact},Newtonsoft.Json.Formatting.Indented));EditorApplication.isPlaying=false;}
