  IEnumerator Ready(string scene){float until=Time.unscaledTime+20;while(Time.unscaledTime<until&&(!L.Ready||SceneManager.GetActiveScene().name!=scene||scene=="Home"&&GameObject.Find("Play")==null||scene=="Gameplay"&&GameObject.Find("Bottle 1")==null))yield return null;yield return null;yield return null;Check(L.Ready&&SceneManager.GetActiveScene().name==scene,"Hazır sahne / Localization: "+scene);}
  void AuditLayout(RectTransform safe,int height)
