  IEnumerator Locale(string code){string before=Stable();Check(L.Select(code),"Manuel dil kaydedildi "+code);yield return null;Check(Stable()==before,"Dil değişimi kaynak/ödül/ilerleme değiştirmez "+code);Check(GameplayProgress.Current.Presentation.manualLocale==code&&L.Code==code,"Aktif ve kayıtlı dil "+code);}
  sealed class SimulatedSystem:SystemLocaleSelector{readonly string code;public SimulatedSystem(string id){code=id;}protected override System.Globalization.CultureInfo GetSystemCulture()=>System.Globalization.CultureInfo.GetCultureInfo(code);protected override SystemLanguage GetApplicationSystemLanguage()=>SystemLanguage.Unknown;}
