   var field=typeof(GameplayProgress).GetField("current",BindingFlags.Static|BindingFlags.NonPublic);var originalLedger=GameplayProgress.Current;string beforeFail=Stable(),localeBefore=L.Code;try{field.SetValue(null,new ProgressLedger(originalLedger.Snapshot,_=>throw new IOException("QA")));Check(!L.Select("de")&&L.Code==localeBefore&&Stable()==beforeFail,"Başarısız dil kaydı locale ve oyuncu verisini değiştirmez");}finally{field.SetValue(null,originalLedger);}
   Check(L.Choose(null,new[]{"tr-TR"})=="tr"&&L.Choose(null,new[]{"en-US"})=="en"&&L.Choose(null,new[]{"de-AT"})=="de","TR / EN / DE cihaz eşleştirmesi");Check(L.Choose(null,new[]{"ja-JP"})=="en"&&L.Choose("pl",new[]{"de-DE"})=="pl","Desteklenmeyen cihaz fallback / manuel öncelik");Check(L.Choose(null,new[]{"pt-PT"})=="pt-BR"&&L.Choose(null,new[]{"pt_BR"})=="pt-BR","Portekizce bölge eşleştirmesi");Check(L.Choose(null,new[]{"ja-JP","fr-CA"})=="fr","Tercih listesinde ilk desteklenen kültür");Check(GameplayProgress.Current.Presentation.coins==1234567&&GameplayProgress.Current.BestStars(1)==3,"Mevcut kullanıcı kaydı korunur");
   foreach(string code in L.Codes)
   {
    yield return Locale(code);Audit("Home",true);Tap("SettingsButton");Audit("Settings",true);Tap("LanguageButton");Audit("LanguagePicker",code=="de");Tap("Locale_"+code);Check(GameObject.Find("LanguagePicker")==null,"Dil seçici gerçek butonla kapanır "+code);Tap("ResourceInfoClose");Tap("MissionsButton");Audit("Daily",code=="de"||code=="pl");Tap("DailyGiftTab");Audit("Gift");Tap("DailyClose");Tap("NavEvents");Tap("EventLegacy");Audit("Events",code=="de");FindFirstObjectByType<Mewgic.Rewards.RewardHubPanel>().Open(2);Audit("Season",code=="de");FindFirstObjectByType<Mewgic.Rewards.RewardHubPanel>().Open(3);Audit("Collection",code=="pl");Tap("RewardHubClose");
    // Every table entry is actually formatted, including grammar/date samples.
