    for(int island=0;island<14;island++)Check(!string.IsNullOrEmpty(L.Resolve(L.Island(island))),"Ada adı "+code+"/"+island);
    foreach(int n in new[]{0,1,2,4,5,21,22})Check(!string.IsNullOrEmpty(L.Resolve(L.V("daily.task.bottles",n))),"Çoğul biçimi "+code+"/"+n);
   }
   Tap("Play");yield return Ready("Gameplay");var app=FindFirstObjectByType<PrototypeApp>();var model=(Puzzle)typeof(PrototypeApp).GetField("puzzle",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(app);var original=model.Export();foreach(string code in L.Codes){yield return Locale(code);Audit("Gameplay",true);FindFirstObjectByType<PawGuide>().OpenMenu();Audit("Paw",code=="de");FindFirstObjectByType<PawGuide>().Close();Tap("Pause");Audit("Pause");Tap("Resume");Check(model.Moves==0&&LevelGenerator.Exact(model.Export(),original),"Dil / yardım / Pause şişe verisini korur "+code);}
   var solution=PuzzleSolver.Solve(model.Export());var m=solution.Moves[0];Tap("Bottle "+(m.Source+1));Tap("Bottle "+(m.Target+1));yield return new WaitForSecondsRealtime(1.05f);Tap("Undo");Check(model.Moves==0&&LevelGenerator.Exact(model.Export(),original),"Yerelleştirilmiş Gameplay Undo");Tap("Restart");Tap("Hint");Check(FindObjectsByType<HintCueGraphic>(FindObjectsSortMode.None).Length==2,"İpucu görseli korunur");Tap("Restart");foreach(var move in solution.Moves){Tap("Bottle "+(move.Source+1));Tap("Bottle "+(move.Target+1));yield return new WaitForSecondsRealtime(1.05f);}Check(model.Won,"Yerelleştirme sonrası gerçek kazanma");foreach(string code in L.Codes){yield return Locale(code);Audit("Win",code=="de");}Tap("ResultHome");yield return Ready("Home");Tap("NavMap");yield return Ready("LevelMap");foreach(string code in L.Codes){yield return Locale(code);var map=FindFirstObjectByType<Mewgic.Map.MapWorld>();map.FocusRegion(1,false);Audit("Map",code=="de");map.OpenChapter(1,0);Audit("MapChapter");Tap("ChapterClose");}Tap("MapHome");yield return Ready("Home");yield return Locale("fr");Check(new SavedLocaleSelector().GetStartupLocale(LocalizationSettings.AvailableLocales).Identifier.Code=="fr","Resmî başlangıç seçicisi kayıtlı tercihi bulur");SessionState.SetString("Part12C.Expected",JsonUtility.ToJson(GameplayProgress.Current.Snapshot));Bind();Check(GameplayProgress.Current.Presentation.manualLocale=="fr","Aynı oturumda gerçek disk yeniden açılışı");Check(L.Missing.Count==0,"Bütün akış sonunda eksik anahtar yok");
  }
  IEnumerator Reload(){yield return Ready("Home");Check(new SimulatedSystem("pt-PT").GetStartupLocale(new DeviceLocaleSelector.BestFitLocales(LocalizationSettings.AvailableLocales)).Identifier.Code=="pt-BR","Resmî cihaz seçicisi / pt-PT doğrudan pt-BR eşleştirmesi");Check(L.Code=="fr"&&GameplayProgress.Current.Presentation.manualLocale=="fr","İki Play Mode / gerçek Boot arasında manuel dil korunur");Check(JsonUtility.ToJson(GameplayProgress.Current.Snapshot)==SessionState.GetString("Part12C.Expected",""),"Boot yeniden girişinde bütün oyuncu verisi aynı");var parent=FindFirstObjectByType<HomeCharacterPresenter>().transform.Find("UI");var instance=Instantiate(UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/UI/MagicalProgressBar.prefab"),parent,false);var bar=instance.GetComponent<MagicalProgressBar>();bar.SetValue(3,5,animate:false);Check(Math.Abs(bar.Percent-.6f)<.0001f&&bar.label.text=="3/5","Mevcut prefab gerçek 3/5 / %60");bar.SetValue(3,5,isLocked:true);Check(bar.label.text==L.Resolve(L.V("common.locked")),"Prefab kilit etiketi yerelleşir");L.Select("de",false);Check(bar.label.text==L.Resolve(L.V("common.locked")),"Prefab açıkken dil anında değişir");L.Select("fr",false);Destroy(instance);yield return null;Audit("Reload_Home",true);}
        void Capture(string filename,int width,int height,bool inset=false)
        {
            var canvas=FindFirstObjectByType<Canvas>();var camera=Camera.main;var p=FindFirstObjectByType<HomeCharacterPresenter>();var safe=p!=null?(RectTransform)p.transform.Find("UI"):(GameObject.Find("Safe area")??GameObject.Find("MapSafeArea"))?.GetComponent<RectTransform>();
            var mode=canvas.renderMode;var oldCam=canvas.worldCamera;float distance=canvas.planeDistance;var oldTarget=camera.targetTexture;var oldActive=RenderTexture.active;Vector2 min=safe!=null?safe.anchorMin:Vector2.zero,max=safe!=null?safe.anchorMax:Vector2.one;
            var rt=new RenderTexture(width,height,24);var tex=new Texture2D(width,height,TextureFormat.RGB24,false);
            try{
                camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;if(inset&&safe!=null){safe.anchorMin=new Vector2(.035f,.04f);safe.anchorMax=new Vector2(.965f,.955f);}
                Canvas.ForceUpdateCanvases();var gameplay=FindFirstObjectByType<GameplayPresentation>();if(gameplay!=null)gameplay.Layout();var pause=GameObject.Find("PauseSafeArea");if(pause!=null&&safe!=null){var pr=(RectTransform)pause.transform;pr.anchorMin=safe.anchorMin;pr.anchorMax=safe.anchorMax;}if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}var map=FindFirstObjectByType<Mewgic.Map.MapWorld>();if(map!=null)map.Layout();var daily=FindFirstObjectByType<Mewgic.Daily.DailyActivitiesPanel>();if(daily!=null&&daily.IsOpen)daily.Layout();var hub=FindFirstObjectByType<Mewgic.Rewards.RewardHubPanel>();if(hub!=null&&hub.IsOpen)hub.Layout();Canvas.ForceUpdateCanvases();
                foreach(var text in FindObjectsByType<TMPro.TMP_Text>(FindObjectsSortMode.None))text.ForceMeshUpdate();FindFirstObjectByType<Mewgic.UI.PawGuide>()?.SendMessage("LateUpdate");foreach(var text in FindObjectsByType<TMP_Text>(FindObjectsSortMode.None)){text.ForceMeshUpdate();if(text.name=="PawMessage")Check(!text.isTextOverflowing,"Pati balonunda taşma yok: "+height);}AuditLayout(safe,height);camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(filename,tex.EncodeToPNG());
            }finally{camera.targetTexture=oldTarget;canvas.renderMode=mode;canvas.worldCamera=oldCam;canvas.planeDistance=distance;if(safe!=null){safe.anchorMin=min;safe.anchorMax=max;}RenderTexture.active=oldActive;DestroyImmediate(tex);rt.Release();DestroyImmediate(rt);Canvas.ForceUpdateCanvases();if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}}
        }
